async function getEmbedding(text) {
  const res = await fetch('https://api.openai.com/v1/embeddings', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${OPENAI_KEY}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: 'text-embedding-3-small',
      input: text.slice(0, 8000)
    })
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error?.message || 'Embedding error');
  return data.data[0].embedding;
}

async function main() {
  console.log(`Embedding ${CHUNKS.length} chunks...`);
  
  // Clear existing
  await supabase.from('corpus_chunks').delete().neq('id', 0);
  console.log('Cleared existing chunks');
  
  let success = 0, errors = 0;
  const batchSize = 10;
  
  for (let i = 0; i < CHUNKS.length; i += batchSize) {
    const batch = CHUNKS.slice(i, i + batchSize);
    await Promise.all(batch.map(async (chunk, j) => {
      try {
        const embedding = await getEmbedding(chunk.content);
        await supabase.from('corpus_chunks').insert({
          content: chunk.content,
          embedding,
          source: chunk.source,
          chunk_index: chunk.chunk_index
        });
        success++;
      } catch(e) {
        console.log(`Error chunk ${i+j}: ${e.message}`);
        errors++;
      }
    }));
    console.log(`Progress: ${Math.min(i+batchSize, CHUNKS.length)}/${CHUNKS.length} (${success} ok, ${errors} err)`);
    await new Promise(r => setTimeout(r, 200));
  }
  
  console.log(`Done! ${success} embedded, ${errors} errors`);
  process.exit(0);
}

main().catch(e => { console.error(e); process.exit(1); });
